package com.p2p.server.social;
import com.p2p.common.social.*;import com.p2p.server.network.social.UdpService;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
class UdpServiceTest {
 UdpService service;Map<String,UdpService.Session> sessions;UdpService.Session alice,bob;DatagramSocket a,b;volatile boolean permitted=true;
 @BeforeEach void start()throws Exception{sessions=new ConcurrentHashMap<>();alice=session("alice",1,1);bob=session("bob",2,1);sessions.put(alice.id,alice);sessions.put(bob.id,bob);service=new UdpService(new UdpService.Host(){public UdpService.Session session(String id){return sessions.get(id);}public Collection<UdpService.Session> recipients(UdpService.Session sender,long conversation){return permitted&&conversation==17?List.of(alice,bob):List.of();}},"test-server","Test",5000,0,0);service.start();a=new DatagramSocket(0,InetAddress.getByName("127.0.0.1"));b=new DatagramSocket(0,InetAddress.getByName("127.0.0.1"));a.setSoTimeout(250);b.setSoTimeout(250);}
 UdpService.Session session(String id,long user,long epoch)throws Exception{byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);return new UdpService.Session(id,user,InetAddress.getByName("127.0.0.1"),epoch,key,System.currentTimeMillis()+60000);}
 @AfterEach void stop(){if(a!=null)a.close();if(b!=null)b.close();if(service!=null)service.close();}
 void send(DatagramSocket socket,byte[] raw,int port)throws Exception{socket.send(new DatagramPacket(raw,raw.length,InetAddress.getByName("127.0.0.1"),port));}
 byte[] receive(DatagramSocket socket)throws Exception{byte[] raw=new byte[1201];DatagramPacket packet=new DatagramPacket(raw,raw.length);socket.receive(packet);return Arrays.copyOf(raw,packet.getLength());}
 Map<String,Object> body(UdpService.Session s,String type,long seq,long ts){Map<String,Object> p=new LinkedHashMap<>();p.put("v",2);p.put("sessionId",s.id);p.put("keyEpoch",s.keyEpoch);p.put("type",type);p.put("seq",seq);p.put("ts",ts);if(type.equals("TYPING")){p.put("conversationId",17);p.put("typing",true);}return p;}
 byte[] packet(UdpService.Session s,String type,long seq)throws Exception{return UdpCodec.sign(body(s,type,seq,System.currentTimeMillis()),s.key,false);}
 void register(DatagramSocket socket,UdpService.Session s,long seq)throws Exception{send(socket,packet(s,"UDP_REGISTER",seq),service.getTypingPort());Map<String,Object> reply=UdpCodec.verify(receive(socket),s.key,true);assertEquals("UDP_REGISTERED",reply.get("type"));assertEquals(s.id,reply.get("sessionId"));}
 void dropped(DatagramSocket socket)throws Exception{assertThrows(SocketTimeoutException.class,()->receive(socket));}
 @Test void discoveryEchoIsBoundedAndRejectsTinyInvalidPackets()throws Exception{String nonce=UUID.randomUUID().toString().replace("-","");byte[] request=Json.MAPPER.writeValueAsBytes(Map.of("protocolVersion",2,"type","DISCOVER","nonce",nonce,"padding"," ".repeat(300)));send(a,request,service.getDiscoveryPort());byte[] reply=receive(a);assertTrue(reply.length<=request.length);Map<String,Object> offer=UdpCodec.outer(reply);assertEquals("OFFER",offer.get("type"));assertEquals(nonce,offer.get("nonce"));assertFalse(offer.containsKey("users"));assertFalse(offer.containsKey("udpKey"));send(a,Json.MAPPER.writeValueAsBytes(Map.of("protocolVersion",2,"type","DISCOVER","nonce",nonce)),service.getDiscoveryPort());dropped(a);}
 @Test void typingUsesRecipientKeyAndRejectsReplayReflectionAndEndpointForgery()throws Exception{register(a,alice,1);register(b,bob,1);byte[] typing=packet(alice,"TYPING",2);send(a,typing,service.getTypingPort());byte[] delivered=receive(b);Map<String,Object> result=UdpCodec.verify(delivered,bob.key,true);assertEquals("TYPING",result.get("type"));assertEquals(1,((Number)result.get("actorId")).intValue());assertTrue(((Number)result.get("expiresAt")).longValue()>System.currentTimeMillis());assertThrows(Exception.class,()->UdpCodec.verify(delivered,alice.key,true));send(a,typing,service.getTypingPort());dropped(b);
  send(a,UdpCodec.sign(body(alice,"TYPING",3,System.currentTimeMillis()),alice.key,true),service.getTypingPort());dropped(b);
  send(a,UdpCodec.sign(body(alice,"TYPING",4,System.currentTimeMillis()-31000),alice.key,false),service.getTypingPort());dropped(b);
  try(DatagramSocket forged=new DatagramSocket(0,InetAddress.getByName("127.0.0.1"))){forged.setSoTimeout(250);send(forged,packet(alice,"TYPING",5),service.getTypingPort());dropped(b);register(forged,alice,6);}
  byte[] key=alice.key.clone();key[0]^=1;send(a,UdpCodec.sign(body(alice,"TYPING",7,System.currentTimeMillis()),key,false),service.getTypingPort());dropped(b);
 }
 @Test void refreshEpochRevocationAndCurrentPolicyStopTyping()throws Exception{register(a,alice,1);register(b,bob,1);byte[] old=packet(alice,"UDP_REGISTER",2);alice.active=false;alice=session("alice",1,2);sessions.put(alice.id,alice);send(a,old,service.getTypingPort());dropped(a);register(a,alice,1);permitted=false;send(a,packet(alice,"TYPING",2),service.getTypingPort());dropped(b);permitted=true;alice.active=false;send(a,packet(alice,"UDP_REGISTER",3),service.getTypingPort());dropped(a);send(a,new byte[1201],service.getTypingPort());dropped(a);}
}

